/* Loop #12 C verification harness: CURVE25519 KEX full flow (client side).
 *
 * Mirrors the MoonBit kexflow package (src/kexflow/) against OpenSSH's ORIGINAL
 * C code on vectors generated by kexflow_python_ref.py:
 *
 *   - crypto_scalarmult_curve25519: real smult_curve25519_ref.c (OpenSSH)
 *   - mpint encoding: REAL sshbuf_put_bignum2_bytes (sshbuf.c + getput-basic)
 *   - exchange hash input assembly: transcribed from kexgen.c:48-96 (kex_sshbuf.c
 *     helpers + SHA-256 from BSD sha2.c)
 *   - SHA-256: BSD sha2.c (same as Loops #5/#6/#9)
 *   - KDF derive_key: transcribed from kex.c:1069-1118 (annotated)
 *
 * Expected values are COMPUTED by python cryptography - never hand-copied.
 */

#include <stdio.h>
#include <stdlib.h>
