#include "sha2_stub.h"
#include "bsd-sha2.h"

/* OpenSSH originals pulled into this single TU */
#include "smult_curve25519_ref.c"          /* djb ref scalarmult */
#include "kex_sshbuf.c"                     /* sshbuf core */
#include "kex_sshbuf_getput_basic.c"        /* put_bignum2_bytes */
#include "sha2.c"                           /* BSD SHA-256 */
#include "chacha.c"                         /* chacha20 keystream */
#include "poly1305.c"                       /* poly1305 MAC */

