#include "_kexflow_kat.h"

/* Test counter */
static int g_fails = 0;
static int g_passes = 0;

#define CHECK(cond, label) do { \
    if (!(cond)) { \
        fprintf(stderr, "FAIL: %s (line %d)\n", label, __LINE__); \
        g_fails++; \
    } else { \
        g_passes++; \
    } \
} while (0)

/* ---------------- hex helpers (for inline literal vectors not in KAT header) ---------------- */

static void hex_print(const unsigned char *b, size_t n, char *out)
{
    static const char H[] = "0123456789abcdef";
    for (size_t i = 0; i < n; i++) {
        out[2*i]   = H[b[i] >> 4];
        out[2*i+1] = H[b[i] & 0xf];
    }
    out[2*n] = '\0';
}

/* ---------------- kex_gen_hash (kexgen.c:48-96, transcribed) ---------------- */

static void kex_gen_hash_compute(
    const unsigned char *V_C, size_t V_C_len,
    const unsigned char *V_S, size_t V_S_len,
    const unsigned char *I_C, size_t I_C_len,
    const unsigned char *I_S, size_t I_S_len,
    const unsigned char *K_S, size_t K_S_len,
    const unsigned char *e,   size_t e_len,
    const unsigned char *f,   size_t f_len,
    const unsigned char *K,   size_t K_len,
    unsigned char *H_out)
{
    SHA2_CTX ctx;
    SHA256Init(&ctx);

    unsigned char u32buf[4];
    unsigned char type_byte = 20;  /* SSH2_MSG_KEXINIT */

    /* V_C: u32(len) || V_C */
    u32buf[0] = (V_C_len >> 24) & 0xff;
    u32buf[1] = (V_C_len >> 16) & 0xff;
    u32buf[2] = (V_C_len >>  8) & 0xff;
    u32buf[3] = (V_C_len      ) & 0xff;
    SHA256Update(&ctx, u32buf, 4);
    SHA256Update(&ctx, V_C, V_C_len);

    /* V_S: u32(len) || V_S */
    u32buf[0] = (V_S_len >> 24) & 0xff;
    u32buf[1] = (V_S_len >> 16) & 0xff;
    u32buf[2] = (V_S_len >>  8) & 0xff;
    u32buf[3] = (V_S_len      ) & 0xff;
    SHA256Update(&ctx, u32buf, 4);
    SHA256Update(&ctx, V_S, V_S_len);

    /* I_C with fake header: u32(|I_C|+1) + u8(20) + I_C */
    {
        size_t L = I_C_len + 1;
        u32buf[0] = (L >> 24) & 0xff;
        u32buf[1] = (L >> 16) & 0xff;
        u32buf[2] = (L >>  8) & 0xff;
        u32buf[3] = (L      ) & 0xff;
        SHA256Update(&ctx, u32buf, 4);
        SHA256Update(&ctx, &type_byte, 1);
        SHA256Update(&ctx, I_C, I_C_len);
    }

    /* I_S with fake header: u32(|I_S|+1) + u8(20) + I_S */
    {
        size_t L = I_S_len + 1;
        u32buf[0] = (L >> 24) & 0xff;
        u32buf[1] = (L >> 16) & 0xff;
        u32buf[2] = (L >>  8) & 0xff;
        u32buf[3] = (L      ) & 0xff;
        SHA256Update(&ctx, u32buf, 4);
        SHA256Update(&ctx, &type_byte, 1);
        SHA256Update(&ctx, I_S, I_S_len);
    }

    /* K_S: u32(len) || K_S */
    u32buf[0] = (K_S_len >> 24) & 0xff;
    u32buf[1] = (K_S_len >> 16) & 0xff;
    u32buf[2] = (K_S_len >>  8) & 0xff;
    u32buf[3] = (K_S_len      ) & 0xff;
    SHA256Update(&ctx, u32buf, 4);
    SHA256Update(&ctx, K_S, K_S_len);

    /* e: u32(len) || e */
    u32buf[0] = (e_len >> 24) & 0xff;
    u32buf[1] = (e_len >> 16) & 0xff;
    u32buf[2] = (e_len >>  8) & 0xff;
    u32buf[3] = (e_len      ) & 0xff;
    SHA256Update(&ctx, u32buf, 4);
    SHA256Update(&ctx, e, e_len);

    /* f: u32(len) || f */
    u32buf[0] = (f_len >> 24) & 0xff;
    u32buf[1] = (f_len >> 16) & 0xff;
    u32buf[2] = (f_len >>  8) & 0xff;
    u32buf[3] = (f_len      ) & 0xff;
    SHA256Update(&ctx, u32buf, 4);
    SHA256Update(&ctx, f, f_len);

    /* K as mpint: u32(mpint_len) [+ 0x00 if MSB set] || K_stripped */
    size_t K_strip_start = 0;
    while (K_strip_start < K_len && K[K_strip_start] == 0)
        K_strip_start++;
    size_t K_strip_len = K_len - K_strip_start;
    int prepend = (K_strip_len > 0 && (K[K_strip_start] & 0x80));
    size_t mpint_len = K_strip_len + (prepend ? 1 : 0);
    u32buf[0] = (mpint_len >> 24) & 0xff;
    u32buf[1] = (mpint_len >> 16) & 0xff;
    u32buf[2] = (mpint_len >>  8) & 0xff;
    u32buf[3] = (mpint_len      ) & 0xff;
    SHA256Update(&ctx, u32buf, 4);
    if (prepend) {
        unsigned char zero = 0;
        SHA256Update(&ctx, &zero, 1);
    }
    SHA256Update(&ctx, K + K_strip_start, K_strip_len);

    SHA256Final(H_out, &ctx);
}

/* ---------------- derive_key (kex.c:1069, transcribed) ---------------- */

static void derive_single(
    char letter,
    const unsigned char *K, size_t K_len,
    const unsigned char *H, size_t H_len,
    const unsigned char *session_id, size_t session_id_len,
    int need,
    unsigned char *out)
{
    SHA2_CTX ctx;
    unsigned char digest[32];
    int have = 0;

    while (have < need) {
        SHA256Init(&ctx);
        SHA256Update(&ctx, K, K_len);
        SHA256Update(&ctx, H, H_len);
        if (have > 0) {
            /* Kn: SHA256(K || H || K1 || ... || Kn-1) -- no session_id */
            SHA256Update(&ctx, out, have);
        } else {
            /* K1: SHA256(K || H || letter || session_id) */
            unsigned char lbuf = (unsigned char)letter;
            SHA256Update(&ctx, &lbuf, 1);
            SHA256Update(&ctx, session_id, session_id_len);
        }
        SHA256Final(digest, &ctx);
        int copy = (need - have < 32) ? (need - have) : 32;
        memcpy(out + have, digest, copy);
        have += copy;
    }
}

/* ---------------- test V1: parse client KEXINIT payload ---------------- */

static void test_v1_parse_kexinit(void)
{
    struct sshbuf *b = sshbuf_new();
    if (b == NULL) { fprintf(stderr, "FAIL: V1 sshbuf_new\n"); g_fails++; return; }
    if (sshbuf_put(b, V1_IC_payload, V1_IC_payload_len) != 0) {
        fprintf(stderr, "FAIL: V1 sshbuf_put\n"); g_fails++; sshbuf_free(b); return;
    }

    unsigned char cookie[16];
    if (sshbuf_get(b, cookie, 16) != 0) {
        fprintf(stderr, "FAIL: V1 cookie read\n"); g_fails++; sshbuf_free(b); return;
    }
    CHECK(memcmp(cookie, V1_cookie, 16) == 0, "V1 cookie match");

    for (int i = 0; i < 10; i++) {
        unsigned char *s = NULL;
        size_t slen = 0;
        if (sshbuf_get_string(b, &s, &slen) != 0) {
            fprintf(stderr, "FAIL: V1 string %d\n", i); g_fails++; sshbuf_free(b); return;
        }
        free(s);
    }

    unsigned char follows;
    if (sshbuf_get_u8(b, &follows) != 0) {
        fprintf(stderr, "FAIL: V1 follows\n"); g_fails++; sshbuf_free(b); return;
    }
    CHECK(follows == 0, "V1 follows=0");

    unsigned int reserved;
    if (sshbuf_get_u32(b, &reserved) != 0) {
        fprintf(stderr, "FAIL: V1 reserved\n"); g_fails++; sshbuf_free(b); return;
    }
    CHECK(reserved == 0, "V1 reserved=0");

    CHECK(sshbuf_len(b) == 0, "V1 payload fully consumed");
    sshbuf_free(b);
}

/* ---------------- test V3: H + derived keys ---------------- */

static void test_v3_full_negotiation(void)
{
    /* Use the server I_S and K_S blob from the KAT (computed by Python reference). */
    unsigned char H[32];
    kex_gen_hash_compute(
        (unsigned char *)"SSH-2.0-OpenSSH_8.9", 19,
        (unsigned char *)"SSH-2.0-OpenSSH_9.5", 19,
        V1_IC_payload, V1_IC_payload_len,
        V3_server_I_S, V3_server_I_S_len,
        V3_K_S_blob, V3_K_S_blob_len,
        V2_client_e, V2_client_e_len,
        V3_server_f, V3_server_f_len,
        V3_K, V3_K_len,
        H
    );

    char hex_buf[65];
    hex_print(H, 32, hex_buf);
    printf("V3 H: %s\n", hex_buf);
    CHECK(memcmp(H, V3_H, 32) == 0, "V3 H matches KAT");

    /* Derive keys using C..F */
    unsigned char key_C[64], key_D[64], key_E[64], key_F[64];
    derive_single('C', V3_K, V3_K_len, H, 32, H, 32, 64, key_C);
    derive_single('D', V3_K, V3_K_len, H, 32, H, 32, 64, key_D);
    derive_single('E', V3_K, V3_K_len, H, 32, H, 32, 64, key_E);
    derive_single('F', V3_K, V3_K_len, H, 32, H, 32, 64, key_F);

    CHECK(memcmp(key_C, V3_enc_key_ctos_C, 64) == 0, "V3 enc_key_C matches KAT");
    CHECK(memcmp(key_D, V3_enc_key_stoc_D, 64) == 0, "V3 enc_key_D matches KAT");

    int all_zero_C = 1;
    for (int i = 0; i < 64; i++) if (key_C[i] != 0) all_zero_C = 0;
    CHECK(!all_zero_C, "V3 key C non-zero");
    CHECK(memcmp(key_C, key_D, 64) != 0, "V3 key C != key D");
}

/* ---------------- test V4: AEAD first frame ---------------- */

static void test_v4_aead_first_frame(void)
{
    /* Use V4_key64_ctos + V4_header4 + V4_plaintext to encrypt and verify
     * the wire output matches the KAT exactly. */
    unsigned char hdr_ct[4];
    unsigned char pld_ct[7];
    unsigned char seqbuf[8] = {0,0,0,0,0,0,0,0};  /* seq=0 */
    unsigned char ctr_zero[8] = {0,0,0,0,0,0,0,0};
    /* OpenSSH chachapoly uses LE u32 counter; "one" = {1,0,0,0,0,0,0,0} */
    unsigned char ctr_one[8]  = {1,0,0,0,0,0,0,0};
    unsigned char zeros[32] = {0};

    /* Poly key = chacha20(K_main, IV=seqbuf, ctr=0) on 32 zeros */
    struct chacha_ctx main_ctx;
    chacha_keysetup(&main_ctx, V4_key64_ctos, 256);
    chacha_ivsetup(&main_ctx, seqbuf, ctr_zero);
    unsigned char poly_key[32];
    chacha_encrypt_bytes(&main_ctx, zeros, poly_key, 32);  /* encrypt zeros → poly_key */

    /* Header CT = chacha20(K_header, IV=seqbuf, ctr=0) on header4 */
    struct chacha_ctx header_ctx;
    chacha_keysetup(&header_ctx, V4_key64_ctos + 32, 256);
    chacha_ivsetup(&header_ctx, seqbuf, ctr_zero);
    {
        unsigned char hdr_copy[4];
        memcpy(hdr_copy, V4_header4, 4);
        chacha_encrypt_bytes(&header_ctx, hdr_copy, hdr_ct, 4);
    }

    /* Payload CT = chacha20(K_main, IV=seqbuf, ctr=1) on plaintext */
    chacha_ivsetup(&main_ctx, seqbuf, ctr_one);
    {
        unsigned char pld_copy[7];
        memcpy(pld_copy, V4_plaintext, 7);
        chacha_encrypt_bytes(&main_ctx, pld_copy, pld_ct, 7);
    }

    /* Tag = poly1305(poly_key, hdr_ct || pld_ct) */
    unsigned char body[11];
    memcpy(body, hdr_ct, 4);
    memcpy(body + 4, pld_ct, 7);
    unsigned char tag[16];
    poly1305_auth(tag, body, 11, poly_key);

    /* Compose wire = hdr_ct || pld_ct || tag */
    unsigned char wire[27];
    memcpy(wire, hdr_ct, 4);
    memcpy(wire + 4, pld_ct, 7);
    memcpy(wire + 11, tag, 16);

    CHECK(memcmp(wire, V4_aead_wire, 27) == 0, "V4 AEAD wire matches KAT");
}

/* ---------------- test V5: tampered variants ---------------- */

static void test_v5_tampered(void)
{
    CHECK(V5_bad_ks_reply[0] == 0x1f, "V5a reply type=KEX_ECDH_REPLY");
    CHECK(V5_bad_sig_reply[0] == 0x1f, "V5b reply type=KEX_ECDH_REPLY");

    /* V5c: zero K = 32 zero bytes */
    int all_zero = 1;
    for (size_t i = 0; i < V5_zero_K_len; i++) if (V5_zero_K[i] != 0) all_zero = 0;
    CHECK(all_zero, "V5c zero K is all zeros");
    CHECK(V5_zero_K_len == 32, "V5c zero K length 32");
}

/* ---------------- main ---------------- */

int main(void)
{
    printf("=== Loop #12 KEX flow C harness ===\n");

    test_v1_parse_kexinit();
    test_v3_full_negotiation();
    test_v4_aead_first_frame();
    test_v5_tampered();

    printf("PASSED: %d, FAILED: %d\n", g_passes, g_fails);
    return g_fails == 0 ? 0 : 1;
}
